236	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
237	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
238	        if (currentOwner == null) {
239	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
240	        }
241	        currentOwner.setAddress(ownerFieldsDto.getAddress());
242	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
243	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
244	        addressResolver.resolve(currentOwner);
245	        currentOwner.setCity(ownerFieldsDto.getCity());
246	        currentOwner.setTitle(ownerFieldsDto.getTitle() == null ? null : ownerFieldsDto.getTitle().getValue());
247	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
248	        currentOwner.setLastName(ownerFieldsDto.getLastName());
249	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
250	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
251	        this.clinicService.saveOwner(currentOwner);
252	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
253	    }
