269	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
270	        Owner owner = this.clinicService.findOwnerById(ownerId);
271	        if (owner == null) {
272	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
273	        }
274	        HttpHeaders headers = new HttpHeaders();
275	        Pet pet = petMapper.toPet(petFieldsDto);
276	        owner.setId(ownerId);
277	        pet.setOwner(owner);
278	        pet.getType().setName(null);
279	        this.clinicService.savePet(pet);
280	        PetDto petDto = petMapper.toPetDto(pet);
281	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
282	            .buildAndExpand(pet.getId()).toUri());
283	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
284	    }
