286	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
287	    @Override
288	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
289	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
290	        if (currentOwner != null) {
291	            Pet currentPet = this.clinicService.findPetById(petId);
292	            if (currentPet != null) {
293	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
294	                currentPet.setName(petFieldsDto.getName());
295	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
296	                this.clinicService.savePet(currentPet);
297	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
298	            }
299	        }
300	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
301	    }
