22	/**
23	 * Guards owner creation against household duplicates. Because a household is keyed on last name
24	 * and postcode, an owner whose {@link Households#householdId(Owner) household identifier} already
25	 * belongs to an existing owner is a second member of that household and is rejected. Setting
26	 * {@code sharesHousehold} declares the owner an intentional household member and bypasses the
27	 * block.
28	 */
29	@Component
30	public class HouseholdDuplicateValidator {
31	
32	    private final Households households;
33	
34	    public HouseholdDuplicateValidator(Households households) {
35	        this.households = households;
36	    }
37	
38	    /**
39	     * Reject {@code candidate} when it is a second member of an existing household, unless it
40	     * declares itself a shared-household member.
41	     *
42	     * @param candidate       the owner about to be created, with its {@code householdId} already set
43	     * @param sharesHousehold whether the owner opted into a shared household, bypassing the block
44	     * @throws HouseholdDuplicateException if another owner already belongs to the candidate's
45	     * household and {@code sharesHousehold} is {@code false}
46	     */
47	    public void validate(Owner candidate, boolean sharesHousehold) {
48	        if (sharesHousehold) {
49	            return;
50	        }
51	        if (!households.findMembers(candidate).isEmpty()) {
52	            throw new HouseholdDuplicateException(candidate.getHouseholdId());
53	        }
54	    }
55	}
