18	
19	import java.util.Comparator;
20	import java.util.Objects;
21	
22	import org.springframework.samples.petclinic.model.Owner;
23	import org.springframework.samples.petclinic.service.ClinicService;
24	import org.springframework.stereotype.Component;
25	
26	/**
27	 * Flags soft duplicates on owner creation. Unlike the hard {@link HouseholdDuplicateValidator}
28	 * (which rejects a second member of an existing household), a soft match never blocks creation:
29	 * when an existing owner already shares the candidate's last name and postcode but carries a
30	 * different telephone, the candidate is recorded as a possible duplicate of that owner.
31	 */
32	@Component
33	public class PossibleDuplicateDetector {
34	
35	    private final ClinicService clinicService;
36	
37	    public PossibleDuplicateDetector(ClinicService clinicService) {
38	        this.clinicService = clinicService;
39	    }
40	
41	    /**
42	     * Record whether {@code candidate} is a possible duplicate of an existing owner. Sets
43	     * {@code possibleDuplicate} true and {@code possibleDuplicateOf} to the earliest existing owner
44	     * that shares the candidate's last name and postcode but has a different telephone; otherwise
45	     * sets {@code possibleDuplicate} false and leaves {@code possibleDuplicateOf} unset.
46	     *
47	     * @param candidate the owner about to be created, with its fields already normalized
48	     */
49	    public void detect(Owner candidate) {
50	        Owner match = findMatch(candidate);
51	        candidate.setPossibleDuplicate(match != null);
52	        if (match != null) {
53	            candidate.setPossibleDuplicateOf(match.getId());
54	        }
55	    }
56	
57	    private Owner findMatch(Owner candidate) {
58	        if (candidate.getPostcode() == null) {
59	            return null;
60	        }
61	        return clinicService.findOwnerByLastNameIgnoreCase(candidate.getLastName()).stream()
62	            .filter(existing -> !existing.isDeleted())
63	            .filter(existing -> candidate.getPostcode().equals(existing.getPostcode()))
64	            .filter(existing -> !Objects.equals(candidate.getTelephone(), existing.getTelephone()))
65	            .min(Comparator.comparing(Owner::getId))
66	            .orElse(null);
67	    }
68	}
