49	        rejectIfBlank(errors, "firstName", owner.getFirstName());
50	        rejectIfBlank(errors, "lastName", owner.getLastName());
51	        rejectIfMissingAddress(errors, owner);
52	        rejectIfBlank(errors, "city", owner.getCity());
