28	/**
29	 * Rejects owner emails whose domain belongs to a known disposable-email provider.
30	 * <p>
31	 * Validation runs only when a syntactically usable email is present; its shape is enforced
32	 * declaratively by the DTO's {@code @Email} constraint. Registered on the owner request binder
33	 * so a disposable domain surfaces through the same {@code BindingResult} as the other
34	 * owner-field checks, yielding a 400 response.
35	 */
36	@Component
37	public class DisposableEmailDomainValidator implements Validator {
38	
39	    private static final Set<String> DISPOSABLE_DOMAINS = Set.of(
40	        "mailinator.com",
41	        "tempmail.com",
42	        "guerrillamail.com");
43	
44	    @Override
45	    public boolean supports(Class<?> clazz) {
46	        return OwnerFieldsDto.class.isAssignableFrom(clazz);
47	    }
48	
49	    @Override
50	    public void validate(Object target, Errors errors) {
51	        OwnerFieldsDto owner = (OwnerFieldsDto) target;
52	        String domain = domainOf(owner.getEmail());
53	        if (domain != null && DISPOSABLE_DOMAINS.contains(domain)) {
54	            errors.rejectValue("email", "email.disposableDomain",
55	                "email domain is not accepted");
56	        }
57	    }
58	
59	    /**
60	     * Extract the lower-cased domain from an email address, or {@code null} when none is present.
61	     */
62	    private String domainOf(String email) {
63	        if (!StringUtils.hasText(email)) {
64	            return null;
65	        }
66	        int at = email.lastIndexOf('@');
67	        if (at < 0 || at == email.length() - 1) {
68	            return null;
69	        }
70	        return email.substring(at + 1).trim().toLowerCase(Locale.ROOT);
71	    }
72	}
