16	package org.springframework.samples.petclinic.service;
17	
18	import java.util.Collection;
19	import java.util.HashSet;
20	import java.util.Set;
21	
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Ensures a freshly generated {@code customerCode} does not collide with one an existing owner
26	 * already holds. When the base code is free it is returned unchanged; otherwise {@code '-<n>'} is
27	 * appended, using the smallest {@code n} of 2 or more that yields a code no existing owner holds.
28	 */
29	@Component
30	public class CustomerCodeDeduplicator {
31	
32	    /**
33	     * De-duplicate {@code baseCode} against the codes already in use.
34	     *
35	     * @param baseCode      the freshly generated customer code
36	     * @param existingCodes the customer codes already held by existing owners
37	     * @return {@code baseCode} when it is free, otherwise {@code '<baseCode>-<n>'} with the smallest
38	     * {@code n} of 2 or more that is not already taken
39	     */
40	    public String deDuplicate(String baseCode, Collection<String> existingCodes) {
41	        Set<String> taken = new HashSet<>(existingCodes);
42	        if (!taken.contains(baseCode)) {
43	            return baseCode;
44	        }
45	        for (int n = 2; ; n++) {
46	            String candidate = baseCode + "-" + n;
47	            if (!taken.contains(candidate)) {
48	                return candidate;
49	            }
50	        }
51	    }
52	}
