16	package org.springframework.samples.petclinic.service;
17	
18	import org.springframework.stereotype.Component;
19	
20	import java.nio.charset.StandardCharsets;
21	import java.security.MessageDigest;
22	import java.security.NoSuchAlgorithmException;
23	
24	/**
25	 * Formats an owner's {@code customerCode} as {@code '<REGION>-<HASH8>'}, where {@code REGION}
26	 * is the owner's region code and {@code HASH8} is the first eight upper-case hex characters of
27	 * the SHA-256 digest over the owner's identity ({@code normalizedTelephone + lastName})
28	 * (e.g. {@code 'NSW-A1B2C3D4'}). The code no longer carries a sequence number.
29	 */
30	@Component
31	public class CustomerCodeGenerator {
32	
33	    /** Number of leading hex characters of the SHA-256 digest kept as the hash segment. */
34	    private static final int HASH_LENGTH = 8;
35	
36	    /**
37	     * Build the customer code from the owner's region and identity.
38	     *
39	     * @param region             the owner's region code (the leading {@code <REGION>} segment)
40	     * @param normalizedTelephone the owner's telephone in its canonical (E.164) form
41	     * @param lastName           the owner's last name
42	     * @return the formatted customer code {@code '<REGION>-<HASH8>'}
43	     */
44	    public String generate(String region, String normalizedTelephone, String lastName) {
45	        return region + "-" + hash(normalizedTelephone + lastName);
46	    }
47	
48	    private String hash(String identity) {
49	        byte[] digest = sha256(identity);
50	        StringBuilder hex = new StringBuilder(HASH_LENGTH);
51	        for (int i = 0; hex.length() < HASH_LENGTH; i++) {
52	            hex.append(String.format("%02X", digest[i]));
53	        }
54	        return hex.substring(0, HASH_LENGTH);
55	    }
56	
57	    private byte[] sha256(String value) {
58	        try {
59	            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
60	        }
61	        catch (NoSuchAlgorithmException e) {
62	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
63	        }
64	    }
65	}
